parameters.jsCode:
// DETERMINISTIC NODE — "Prepare & Validate Input"
// n8n Code node (Run Once for All Items). Pure rules, no AI.
//
// Purpose:
//  - Consolidate the raw form + extracted-file data into clean fields.
//  - Decide is_valid using simple, auditable rules (presence + minimum length).
// The downstream IF node routes on `is_valid`; the fallback branch handles invalid input.

// The Form Trigger output (name, email, JD textarea) is on the trigger node.
// The Extract-from-File node output puts the resume text on `text` of THIS item.
const form = $('Submit JD + Resume').first().json;

const jdText = (form['Job Description'] || '').toString().trim();
const candidateName = (form['Candidate Name'] || '').toString().trim();
const candidateEmail = (form['Candidate Email'] || '').toString().trim();

// Resume text comes from the Extract from File node (PDF/DOCX/TXT -> text).
const resumeText = ($json.text || '').toString().trim();

const MIN_LEN = 50; // a real JD/resume is well over 50 chars; below this it's junk/empty.

const errors = [];
if (jdText.length < MIN_LEN) errors.push('Job Description is missing or too short.');
if (resumeText.length < MIN_LEN) errors.push('Resume could not be read or is too short (is it a scanned/image PDF?).');

return [{
  json: {
    candidate_name: candidateName || 'Candidate',
    candidate_email: candidateEmail || '',
    jd_text: jdText,
    resume_text: resumeText,
    is_valid: errors.length === 0,
    validation_error: errors.join(' ')
  }
}];

