parameters.jsCode:
// DETERMINISTIC NODE — "Weight & Bucket"
// n8n Code node (Run Once for All Items). Pure math + rules, no AI.
//
// This is the core "AI proposes, deterministic decides" boundary:
//  - The Fit Analyst (AI) returns per-dimension sub-scores (0-100) + matched/missing skills.
//  - THIS node applies fixed weights to compute the final score, an independent coverage
//    cross-check, and the STRONG/MODERATE/WEAK category. None of this is left to the AI,
//    so scoring is stable, explainable, and auditable.

// Declarative scoring rubric (change weights here, behavior stays predictable).
const WEIGHTS = { skills_match: 0.5, experience: 0.3, projects_relevance: 0.2 };
const THRESHOLDS = { strong: 75, moderate: 50 }; // >=75 STRONG, 50-74 MODERATE, <50 WEAK

const fit = $('Fit Analyst').first().json.output;
const jd = $('JD Requirement Extractor').first().json.output;
const prep = $('Prepare & Validate Input').first().json;

const dim = fit.dimension_scores || {};
const clamp = (n) => Math.max(0, Math.min(100, Number(n) || 0));

const skills = clamp(dim.skills_match);
const experience = clamp(dim.experience);
const projects = clamp(dim.projects_relevance);

// Weighted final score (deterministic).
const final_score = Math.round(
  skills * WEIGHTS.skills_match +
  experience * WEIGHTS.experience +
  projects * WEIGHTS.projects_relevance
);

// Independent cross-check: how many required skills are actually matched?
const required = Array.isArray(jd.required_skills) ? jd.required_skills : [];
const matched = Array.isArray(fit.matched_skills) ? fit.matched_skills : [];
const matchedLower = matched.map((s) => String(s).toLowerCase());
const coveredRequired = required.filter((r) =>
  matchedLower.some((m) => m.includes(String(r).toLowerCase()) || String(r).toLowerCase().includes(m))
);
const coverage_pct = required.length
  ? Math.round((coveredRequired.length / required.length) * 100)
  : 0;

// Category (deterministic routing key).
let category = 'WEAK';
if (final_score >= THRESHOLDS.strong) category = 'STRONG';
else if (final_score >= THRESHOLDS.moderate) category = 'MODERATE';

// Default decision per category (MODERATE is overridden later by the human reviewer).
const decisionByCategory = {
  STRONG: 'Shortlisted (auto)',
  MODERATE: 'Pending human review',
  WEAK: 'Not a fit — feedback sent'
};

return [{
  json: {
    candidate_name: prep.candidate_name,
    candidate_email: prep.candidate_email,
    role_title: jd.role_title || '',
    final_score,
    coverage_pct,
    category,
    decision: decisionByCategory[category],
    weights: WEIGHTS,
    dimension_scores: { skills_match: skills, experience, projects_relevance: projects },
    matched_skills: matched,
    missing_skills: fit.missing_skills || [],
    strengths: fit.strengths || [],
    gaps: fit.gaps || [],
    verdict: fit.verdict || ''
  }
}];

