parameters.jsCode:
// DETERMINISTIC NODE — "Build Report"
// n8n Code node (Run Once for All Items). Converges all 3 branches into one readable report.
//
// Reads the stable evaluation from "Weight & Bucket", the branch's `decision`, and (only on the
// WEAK branch) the coaching output. The Resume Coach reference is wrapped in try/catch because it
// does not run on the STRONG/MODERATE branches — graceful handling of an optional upstream node.

const base = $('Weight & Bucket').first().json;
const decision = $json.decision || base.decision;

let coach = null;
try {
  coach = $('Resume Coach').first().json.output;
} catch (e) {
  coach = null; // Coach only runs on the WEAK branch.
}

const lines = [];
lines.push(`Candidate: ${base.candidate_name}`);
lines.push(`Role: ${base.role_title}`);
lines.push(`Category: ${base.category}   |   Fit Score: ${base.final_score}/100   |   Required-skill coverage: ${base.coverage_pct}%`);
lines.push(`Decision: ${decision}`);
lines.push('');
lines.push(`Verdict: ${base.verdict}`);
lines.push('');
lines.push(`Matched skills: ${(base.matched_skills || []).join(', ') || '—'}`);
lines.push(`Missing skills: ${(base.missing_skills || []).join(', ') || '—'}`);
lines.push('');
lines.push('Strengths:');
(base.strengths || []).forEach((s) => lines.push(`  • ${s}`));
lines.push('Gaps:');
(base.gaps || []).forEach((g) => lines.push(`  • ${g}`));

if (coach) {
  lines.push('');
  lines.push('— Coaching: how to become a stronger fit —');
  lines.push(coach.improvement_summary || '');
  lines.push('Priority skills to learn: ' + (coach.priority_skills_to_learn || []).join(', '));
  lines.push('Resume fixes:');
  (coach.resume_fixes || []).forEach((f) => lines.push(`  • ${f}`));
  if (coach.encouragement) lines.push('');
  if (coach.encouragement) lines.push(coach.encouragement);
}

const report_text = lines.join('\n');

return [{ json: { ...base, decision, coach, report_text } }];

// DETERMINISTIC NODE — "Append to Log File"
// n8n Code node (Run Once for All Items). Tool use + persistence, no external account.
//
// Appends one JSON line per evaluation to a local file so every run is tracked (like a
// lightweight applicant tracker). Wrapped in try/catch and the node has "Continue On Fail"
// enabled, so if file access is not permitted the workflow still completes (graceful fallback).
//
// IMPORTANT: writing files from a Code node requires n8n to allow built-in modules. Start n8n with:
//   NODE_FUNCTION_ALLOW_BUILTIN=fs,os,path npx n8n
// If that env var is not set, this node simply skips logging (it will not break the run).

const b = $json; // output of the "Weight & Bucket" node (plus any human decision merged in)

const row = {
  timestamp: $now.toISO(),            // n8n built-in current time (Luxon)
  candidate_name: b.candidate_name,
  candidate_email: b.candidate_email,
  role_title: b.role_title,
  final_score: b.final_score,
  coverage_pct: b.coverage_pct,
  category: b.category,
  decision: b.decision,
  matched_skills: b.matched_skills,
  missing_skills: b.missing_skills
};

let logged = false;
let log_path = '';
try {
  const fs = require('fs');
  const os = require('os');
  const path = require('path');
  log_path = path.join(os.homedir(), 'jd-resume-fit-runs.jsonl');
  fs.appendFileSync(log_path, JSON.stringify(row) + '\n');
  logged = true;
} catch (err) {
  // Graceful fallback: logging is best-effort. The report is still returned to the user.
  logged = false;
}

return [{ json: { ...b, _log: { logged, log_path, row } } }];

